#include <iostream>
#include <queue>
#include <map>
using namespace std;
typedef map<int,int> mi;

mi edge[7000];
char buf[20][20];
int n,m,vn,from[7000],flow[7000],tox[10][10];

int augment(int s,int t,int cap){
  int total_flow=0;
  for (int f=1; f--;){
    for (int i=vn; i--;) from[i]=-1;
    from[s]=s;
    flow[s]=cap;
    queue<int> q;
    q.push(s);
    while (!q.empty()){
      int x=q.front(); q.pop();
      if (x==t){
        for (int cur=x; cur!=s; cur=from[cur]){
          edge[from[cur]][cur]-=flow[t];
          edge[cur][from[cur]]+=flow[t];
        }
        total_flow+=flow[t];
        break;
      }
      for (auto e=edge[x].begin(); e!=edge[x].end(); e++){
        if (e->second>=cap && from[e->first]==-1){
          from[e->first]=x;
          flow[e->first]=min(e->second,flow[x]);
          q.push(e->first);
        }
      }
    }
  }
  return total_flow;
}

int encode(int x,int y,int t){
  return x+y*n+t*n*n+2;
}

int main(){
  ios::sync_with_stdio(false);
  cin>>n>>m;

  int res=0;
  for (int i=0; i<n; i++){
    for (int j=0; j<n; j++){
      cin>>buf[i][j];
      if (buf[i][j]>'0' && buf[i][j]<='9') edge[0][encode(i,j,0)]=buf[i][j]-'0';
    }
  }
  for (int i=0; i<n; i++) cin>>buf[i];

  static const int dx[]={-1,0,1,0};
  static const int dy[]={0,-1,0,1};

  queue<pair<int,int>> bfs;
  for (int i=n-1; i>=0; i--){
    for (int j=n-1; j>=0; j--){
      if (buf[i][j]=='Z') tox[i][j]=0, bfs.emplace(i,j);
      else tox[i][j]=m+1;
    }
  }

  while (!bfs.empty()){
    auto p=bfs.front(); bfs.pop();
    int i=p.first, j=p.second;
    for (int dir=0; dir<4; dir++){
      int t=tox[i][j];
      int x=i+dx[dir], y=j+dy[dir];
      if (x>=0 && y>=0 && x<n && y<n && buf[x][y]!='Y' && t+1<tox[x][y]){
        tox[x][y]=t+1;
        bfs.emplace(x,y);
      }
    }
  }

  vn=encode(n-1,n-1,m)+1;

  for (int i=0; i<n; i++){
    for (int j=0; j<n; j++){
      for (int t=0; t<m; t++){
        if (t<m) for (int q=0; q<4; q++){
          int x=i+dx[q], y=j+dy[q];
          if (x>=0 && y>=0 && x<n && y<n && buf[x][y]!='Y' && t+1<tox[x][y]+(buf[x][y]>'0' && buf[x][y]<='9') && t<tox[i][j]){
            edge[encode(i,j,t)][encode(x,y,t+1)]=1000;
          }
        }
        if (buf[i][j]>'0' && buf[i][j]<='9'){
          edge[encode(i,j,t)][encode(i,j,m)]=buf[i][j]-'0';
        }
      }
      if (buf[i][j]>'0' && buf[i][j]<='9'){
        edge[encode(i,j,m)][1]=buf[i][j]-'0';
      }
    }
  }

  for (int u=8; u; u/=2) res+=augment(0,1,u);
  cout<<res<<'\n';
}
